// Package httpx holds the gateway's HTTP middleware.
package httpx

import (
	"net"
	"net/http"
	"time"
)

// Recorder receives one observation per finished request.
type Recorder interface {
	ObserveRequest(method, route string, status int, elapsed time.Duration)
}

// Limiter decides whether a client may make another request right now.
type Limiter interface {
	Allow(client string) bool
}

// statusWriter remembers the status code a handler wrote.
type statusWriter struct {
	http.ResponseWriter
	status int
	wrote  bool
}

func (w *statusWriter) WriteHeader(code int) {
	if !w.wrote {
		w.status = code
		w.wrote = true
	}
	w.ResponseWriter.WriteHeader(code)
}

func (w *statusWriter) Write(p []byte) (int, error) {
	if !w.wrote {
		w.status = http.StatusOK
		w.wrote = true
	}
	return w.ResponseWriter.Write(p)
}

// Instrument rate-limits next per client and reports every request to rec
// under route, the pattern the handler is registered for. A rejected request
// is reported too, so the limiter's effect shows up in the request metrics.
func Instrument(rec Recorder, limit Limiter, route string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		if !limit.Allow(clientKey(r)) {
			w.Header().Set("Retry-After", "1")
			http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
			rec.ObserveRequest(r.Method, route, http.StatusTooManyRequests, time.Since(start))
			return
		}
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		rec.ObserveRequest(r.Method, route, sw.status, time.Since(start))
	})
}

// clientKey identifies the caller by address, without the ephemeral port.
func clientKey(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}
